// 6-to-1 multiplexer, one-hot select -> short AND chain, register on
// output (register delay -> higher Fmax).
module TopModule(
    input  [2:0] sel,
    input  [3:0] data0,
    input  [3:0] data1,
    input  [3:0] data2,
    input  [3:0] data3,
    input  [3:0] data4,
    input  [3:0] data5,
    output [3:0] out
);
    wire [3:0] dat;
    wire       sel0 = (sel == 3'd0);
    wire       sel1 = (sel == 3'd1);
    wire       sel2 = (sel == 3'd2);
    wire       sel3 = (sel == 3'd3);
    wire       sel4 = (sel == 3'd4);
    wire       sel5 = (sel == 3'd5);
    wire       seln = ~(sel0 | sel1 | sel2 | sel3 | sel4 | sel5);
    and        a0 (dat, sel0, data0);
    and        a1 (dat, sel1, data1);
    and        a2 (dat, sel2, data2);
    and        a3 (dat, sel3, data3);
    and        a4 (dat, sel4, data4);
    and        a5 (dat, sel5, data5);
    and        an (dat, seln, 4'd0);
    reg  [3:0] outr;
    always @(posedge sel) outr <= dat;
    assign out = outr;
endmodule

